-- 2026-10-15 Token 多语言键清理与补全。
-- 前提：源码与运行库加密备份、隔离恢复校验已完成；仅用独立连接运行，遇首错停止并回滚。
-- 固定删除702个(type,tkey)，审核快照共12076行；首轮必须完整匹配，幂等重放允许0行。
-- 不删除白名单以外的词条、type0分类、现存通知模板或当前type6系统消息配置。
-- 每个待删键的语言集合也固定；发现同键新增未审核语言、部分清理或异常唯一键即中止。
-- 补20条中英词条；10项已知旧文案仅精确匹配旧值时修正，缺/空可补，其余非空人工译文保留。
-- 所有生产表DML与翻译revision更新同一事务；临时主键断言不依赖MySQL 8.0.12不强制的CHECK。
USE token;
SET NAMES utf8mb4 COLLATE utf8mb4_bin;
SET time_zone = '+00:00';
SET @token_i18n_old_isolation = @@SESSION.transaction_isolation;
SET SESSION TRANSACTION ISOLATION LEVEL SERIALIZABLE;
CREATE TEMPORARY TABLE token_i18n_guard (verified TINYINT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
-- 守卫：第一重实际库名核对
-- 守卫：第二重固定token对象及事务引擎核对
-- 守卫：翻译表必要字段存在
-- 守卫：现有key_lang唯一约束完整
-- 守卫：翻译版本配置存在且唯一
CREATE TEMPORARY TABLE token_i18n_delete_keys (
  template_type INT NOT NULL,
  tkey VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  expected_count INT NOT NULL,
  expected_languages JSON NOT NULL,
  PRIMARY KEY(template_type,tkey)
) ENGINE=InnoDB;
CREATE TEMPORARY TABLE token_i18n_seed (
  template_type INT NOT NULL,
  tkey VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  lang VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  before_value TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  after_value TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  patch_mode ENUM('GAP','EXACT') NOT NULL,
  PRIMARY KEY(template_type,tkey,lang)
) ENGINE=InnoDB;
START TRANSACTION;
-- 先锁定唯一翻译版本行；SERIALIZABLE下检查读取也锁住相关键及插入间隙。
SELECT setting_value,revision INTO @token_i18n_revision_before,@token_i18n_revision_number_before FROM token.system_setting WHERE BINARY setting_key=BINARY 'i18n.translations.revision' FOR UPDATE;
-- 守卫：事务内再次核对数据库与版本行
SELECT COUNT(*),SUM(expected_count) INTO @token_i18n_whitelist_keys,@token_i18n_whitelist_rows FROM token_i18n_delete_keys;
-- 守卫：本次固定白名单、语言数量和补丁完整
-- 守卫：禁止将type0分类或type2/4/6配置加入删除白名单
-- 守卫：补丁不能落在删除范围
SELECT COUNT(*) INTO @token_i18n_delete_before FROM token.translates t JOIN token_i18n_delete_keys d ON t.type=d.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=d.tkey;
-- 只接受首次完整快照或已完成后的0行，不接受部分删除后继续掩盖变化。
-- 守卫：删除行数为审核快照或已完成状态
-- 守卫：待删键没有新增未审核语言
-- 守卫：每个待删键也必须完整或已清理
-- 守卫：补丁不存在仅大小写/排序规则等价的非预期键或语言
SET @token_i18n_deleted=0, @token_i18n_inserted=0, @token_i18n_filled=0, @token_i18n_corrected=0, @token_i18n_extra_corrected=0;
-- 仅按固定(type,tkey)内连接白名单删除；绝不按保留集合之外删除。
DELETE t FROM token.translates t JOIN token_i18n_delete_keys d ON t.type=d.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=d.tkey;
SET @token_i18n_deleted=ROW_COUNT();
-- 守卫：实际删除行数与锁定后的检查一致
-- 对缺失行插入；is_del=0沿用内置词条标志，不把它视为软删除状态。
SELECT s.tkey,s.lang,s.after_value,s.template_type,0,CONVERT(0x546f6b656e20e5a49ae8afade8a880e994aee695b4e79086 USING utf8mb4),0,UTC_TIMESTAMP() FROM token_i18n_seed s
WHERE NOT EXISTS (SELECT 1 FROM token.translates t WHERE t.type=s.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=s.tkey AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin=s.lang);
SET @token_i18n_inserted=ROW_COUNT();
-- 只填空正文，不改现有prop/title/is_del等元数据。
UPDATE token.translates t JOIN token_i18n_seed s ON t.type=s.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=s.tkey AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin=s.lang
SET t.tvalue=s.after_value,t.action_time=UTC_TIMESTAMP() WHERE TRIM(COALESCE(t.tvalue,''))='';
SET @token_i18n_filled=ROW_COUNT();
-- 已知旧文案以二进制精确比较；不覆盖不同的非空人工文案。
UPDATE token.translates t JOIN token_i18n_seed s ON t.type=s.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=s.tkey AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin=s.lang
SET t.tvalue=s.after_value,t.action_time=UTC_TIMESTAMP() WHERE s.patch_mode='EXACT' AND BINARY t.tvalue=BINARY s.before_value AND NOT (BINARY t.tvalue <=> BINARY s.after_value);
SET @token_i18n_corrected=ROW_COUNT();
-- TOKEN_I18N_EXTRA_EXACT_FIXES_BEFORE_REVISION
-- 如需附加已审核的其它语言语法修复，仅在此处合并精确旧值补丁并累加@token_i18n_extra_corrected。
SET @token_i18n_total_changed=@token_i18n_deleted+@token_i18n_inserted+@token_i18n_filled+@token_i18n_corrected+@token_i18n_extra_corrected;
-- 守卫：种子涉及的中英文均有非空正文
-- 守卫：白名单删除完成
-- 仅当生产词条发生实际变化时更新翻译版本；幂等重放不改revision或updated_at。
UPDATE token.system_setting SET setting_value=LOWER(UUID()),revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE BINARY setting_key=BINARY 'i18n.translations.revision' AND @token_i18n_total_changed>0;
SET @token_i18n_revision_changed=ROW_COUNT();
-- 守卫：版本更新次数与实际变更一致
-- 守卫：版本号只递增一次或保持原样
COMMIT;
DROP TEMPORARY TABLE token_i18n_seed;
DROP TEMPORARY TABLE token_i18n_delete_keys;
DROP TEMPORARY TABLE token_i18n_guard;
SET SESSION transaction_isolation=@token_i18n_old_isolation;
SELECT JSON_OBJECT('deleted',@token_i18n_deleted,'inserted',@token_i18n_inserted,'filled',@token_i18n_filled,'corrected',@token_i18n_corrected,'extraCorrected',@token_i18n_extra_corrected,'revisionChanged',@token_i18n_revision_changed) AS token_i18n_cleanup_result;
