INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT (BINARY DATABASE()=BINARY 'token' AND (SELECT COUNT(*) FROM token.system_setting WHERE BINARY setting_key=BINARY 'i18n.translations.revision')=1);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT (@token_i18n_whitelist_keys=702 AND @token_i18n_whitelist_rows=12076 AND (SELECT COUNT(*) FROM token_i18n_seed)=30);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token_i18n_delete_keys WHERE template_type NOT IN (1,3,5,7))=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token_i18n_seed s JOIN token_i18n_delete_keys d ON s.template_type=d.template_type AND s.tkey=d.tkey)=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT (@token_i18n_delete_before IN (0,12076));
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token.translates t JOIN token_i18n_delete_keys d ON t.type=d.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=d.tkey WHERE NOT JSON_CONTAINS(d.expected_languages,JSON_QUOTE(CONVERT(t.lang USING utf8mb4))))=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM (SELECT d.template_type,d.tkey,d.expected_count,COUNT(t.id) AS actual_count FROM token_i18n_delete_keys d LEFT JOIN token.translates t ON t.type=d.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=d.tkey GROUP BY d.template_type,d.tkey,d.expected_count HAVING COUNT(t.id)<>0 AND COUNT(t.id)<>d.expected_count) token_i18n_changed_keys)=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token.translates t JOIN token_i18n_seed s ON t.type=s.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_general_ci=s.tkey COLLATE utf8mb4_general_ci AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_unicode_ci=s.lang COLLATE utf8mb4_unicode_ci WHERE NOT (BINARY t.tkey=BINARY s.tkey AND BINARY t.lang=BINARY s.lang))=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT (@token_i18n_deleted=@token_i18n_delete_before);
