INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token_i18n_seed s LEFT JOIN token.translates t ON t.type=s.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=s.tkey AND CONVERT(t.lang USING utf8mb4) COLLATE utf8mb4_bin=s.lang WHERE t.id IS NULL OR TRIM(COALESCE(t.tvalue,''))='')=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT COUNT(*) FROM token.translates t JOIN token_i18n_delete_keys d ON t.type=d.template_type AND CONVERT(t.tkey USING utf8mb4) COLLATE utf8mb4_bin=d.tkey)=0);
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT (@token_i18n_revision_changed=IF(@token_i18n_total_changed>0,1,0));
INSERT INTO token_i18n_guard (verified) SELECT 1 WHERE NOT ((SELECT revision FROM token.system_setting WHERE BINARY setting_key=BINARY 'i18n.translations.revision')=@token_i18n_revision_number_before+IF(@token_i18n_total_changed>0,1,0));
